def fixture(*, completed=True):
    # Non-square400x200: left BA=(100,-100), BC=(100,0), exactly45deg.
    # right BA=(-100,0), BC=(0,100), exactly90deg. Neither answer is
    # generated by joint_angle or by the evaluator under test.
    identity=dict(sample_id="S-f000000",video_id="v_BodyWeightSquats_g01_c01.avi",
        video_path="Data/UCF-101_GYM/BodyWeightSquats/v_BodyWeightSquats_g01_c01.avi",
        video_sha256="1"*64,frame_index=0,timestamp_seconds=0.,width=400,height=200,image_sha256="2"*64)
    points=dict(left_hip=(200.,0.),left_knee=(100.,100.),left_ankle=(200.,100.),
                right_hip=(0.,0.),right_knee=(100.,0.),right_ankle=(100.,100.))
    frame=dict(identity=identity,annotation_status="completed",annotator="SYNTHETIC_TEST_ONLY",
        method="synthetic_fixture",annotated_at="2026-10-21T00:00:00+00:00",
        independent_of_model=True,blinded_to_predictions=True,provenance_note="Analytic fixture; never real label",
        landmarks={j:dict(state="visible",x=x,y=y,reason=None) for j,(x,y) in points.items()})
    if not completed:
        frame.update(annotation_status="pending",annotator=None,method=None,annotated_at=None,
                     independent_of_model=None,blinded_to_predictions=None,provenance_note=None,
                     landmarks={j:dict(state="pending",x=None,y=None,reason="annotation_pending") for j in ref.JOINTS})
    doc=dict(protocol_sha256="3"*64,sampling_sha256="4"*64,frames=[frame])
    manifest=dict(version=ref.VERSION,**ref.STATUS,data_kind="synthetic",protocol_sha256="3"*64,
                  sampling_sha256="4"*64,samples=[dict(identity=identity)])
    prediction=dict(identity=identity,raw_joints={j:dict(x=x/400,y=y/200,status="observed") for j,(x,y) in points.items()},
        processed={s:dict(side=s,feature_id=f"squat_knee_angle_{s}_deg",status="available",gate_action="allow",
                          unit="degrees",value=v,reasons=[]) for s,v in (("left",55.),("right",80.))})
    predictions=dict(version=ref.VERSION,**ref.STATUS,manifest_hash=ref.canonical_hash(manifest),frames=[prediction])
    return manifest,predictions,doc


def run_fixture(m,p,d):
    return ref.evaluate(m,p,ref.ReferenceDocument.model_validate_json(json.dumps(d),strict=True))


def test_known_geometry_nonsquare_units_and_no_accuracy_promotion():
    m,p,d=fixture();r=run_fixture(m,p,d)
    raw=r["branches"]["raw_landmark_px"]["overall"]
    angle=r["branches"]["processed_angle_deg"]["overall"]
    assert raw["n"]==6 and raw["mae"]==0
    assert angle["n"]==2 and angle["mae"]==pytest.approx(10,abs=1e-12)
    assert [x["reference_angle"] for x in r["rows"] if x["branch"]=="processed_angle_deg"]==pytest.approx([45,90],abs=1e-12)
    assert r["validation_status"]=="NOT_VALIDATED" and not r["official_eligibility"] and not r["assessment"]
    assert not r["raw_diagnostic_angle_computed"] and r["accuracy_acceptance_threshold"] is None


def test_euclidean_pixel_error_independent_3_4_5_triangle():
    m,p,d=fixture();p["frames"][0]["raw_joints"]["right_hip"].update(x=3/400,y=4/200)
    r=run_fixture(m,p,d)
    assert r["branches"]["raw_landmark_px"]["overall"]["mae"]==pytest.approx(5/6,abs=1e-12)


@pytest.mark.parametrize("empty",[False,True])
def test_no_reference_is_pending_null_not_zero(empty):
    m,p,d=fixture(completed=False)
    if empty:d["frames"]=[]
    r=run_fixture(m,p,d)
    assert r["status"]=="REFERENCE_PENDING" and r["counts"]["pending_reference_frames"]==1
    for branch,n in (("raw_landmark_px",6),("processed_angle_deg",2)):
        s=r["branches"][branch]["overall"]
        assert s["denominator"]==s["reference_unavailable"]==n and s["n"]==0
        assert s["mae"] is s["median_absolute_error"] is s["p90_absolute_error"] is None


@pytest.mark.parametrize("state",["occluded","out_of_frame","uncertain"])
def test_unavailable_reference_never_guessed(state):
    m,p,d=fixture();d["frames"][0]["landmarks"]["left_knee"]=dict(state=state,x=None,y=None,reason="cannot_locate")
    r=run_fixture(m,p,d)
    assert r["branches"]["raw_landmark_px"]["overall"]["n"]==5
    assert r["branches"]["processed_angle_deg"]["overall"]["n"]==1
    assert next(x for x in r["rows"] if x["joint"]=="left_knee")["absolute_error"] is None


@pytest.mark.parametrize("gate",["degrade","skip"])
def test_saved_gate_not_reopened_by_complete_reference(gate):
    m,p,d=fixture();p["frames"][0]["processed"]["left"].update(status="unavailable",value=None,gate_action=gate,reasons=["feature_quality_blocked"])
    r=run_fixture(m,p,d)
    assert r["branches"]["processed_angle_deg"]["overall"]["n"]==1
    assert r["branches"]["raw_landmark_px"]["overall"]["n"]==6
    assert r["branches"]["processed_angle_deg"]["overall"]["model_unavailable"]==1


@pytest.mark.parametrize("joint",["left_hip","left_ankle"])
def test_reference_zero_vector_is_reason_not_fake_angle(joint):
    m,p,d=fixture();d["frames"][0]["landmarks"][joint]=copy.deepcopy(d["frames"][0]["landmarks"]["left_knee"])
    r=run_fixture(m,p,d);row=next(x for x in r["rows"] if x["branch"]=="processed_angle_deg" and x["side"]=="left")
    assert row["absolute_error"] is row["reference_angle"] is None
    assert row["reference_unavailable_reasons"]==["reference_degenerate_geometry"]


def test_equal_endpoints_distinct_from_knee_remain_zero_angle():
    m,p,d=fixture();d["frames"][0]["landmarks"]["left_hip"]=copy.deepcopy(d["frames"][0]["landmarks"]["left_ankle"])
    r=run_fixture(m,p,d)
