@pytest.mark.parametrize("fault",["wrong_side","missing_joint","duplicate","duplicate_identity_other_id","unknown_joint"])
def test_exact_anatomical_keys_and_duplicates(fault):
    m,p,d=fixture();j=d["frames"][0]["landmarks"]
    if fault=="wrong_side":j["image_left_knee"]=j.pop("left_knee")
    elif fault=="missing_joint":j.pop("left_knee")
    elif fault=="unknown_joint":j["nose"]=copy.deepcopy(j["left_knee"])
    else:
        d["frames"].append(copy.deepcopy(d["frames"][0]))
        if fault=="duplicate_identity_other_id":d["frames"][-1]["identity"]["sample_id"]="another"
    with pytest.raises(ValueError):run_fixture(m,p,d)


