@pytest.mark.parametrize("fault",["status","value","nan","unit","side","feature","missing_prediction","duplicate_prediction","raw_nan","raw_imputed","raw_missing_coordinates","version","protocol","sampling","manifest_hash"])
def test_prediction_and_version_validation(fault):
    m,p,d=fixture();obs=p["frames"][0]["processed"]["left"]
    if fault=="status":obs["gate_action"]="skip"
    elif fault=="value":obs.update(status="unavailable",value=12.,reasons=["blocked"])
    elif fault=="nan":obs["value"]=float("nan")
    elif fault=="unit":obs["unit"]="radians"
    elif fault=="side":obs["side"]="right"
    elif fault=="feature":obs["feature_id"]="squat_knee_angle_right_deg"
    elif fault=="missing_prediction":p["frames"]=[]
    elif fault=="duplicate_prediction":p["frames"].append(copy.deepcopy(p["frames"][0]))
    elif fault=="raw_nan":p["frames"][0]["raw_joints"]["left_knee"]["x"]=float("nan")
    elif fault=="raw_imputed":p["frames"][0]["raw_joints"]["left_knee"]["status"]="imputed"
    elif fault=="raw_missing_coordinates":p["frames"][0]["raw_joints"]["left_knee"]["status"]="missing"
    elif fault=="version":p["version"]="unknown"
    elif fault=="protocol":d["protocol_sha256"]="8"*64
    elif fault=="sampling":d["sampling_sha256"]="8"*64
    else:p["manifest_hash"]="8"*64
    with pytest.raises(ValueError):run_fixture(m,p,d)


