def test_quantiles_weighting_missingness_and_roundtrip():
    assert ref.statistics_for([0.,10.,20.])==dict(n=3,mae=10.,median_absolute_error=10.,p90_absolute_error=18.)
    m,p,d=fixture();r=run_fixture(m,p,d)
    assert r["branches"]["processed_angle_deg"]["clip_side_macro_mae"]==pytest.approx(10)
    assert json.loads(json.dumps(r,allow_nan=False))==r
