def pairs_fixture():
    return [dict(path=f"Data/UCF-101_GYM/BodyWeightSquats/v_BodyWeightSquats_g{g:02d}_c{c:02d}.avi",side=s,
                 metric=dict(action=a)) for g,c,acts in ((1,1,("allow","skip")),(1,2,("skip","allow")),
                  (4,1,("skip","degrade")),(5,1,("allow","allow")),(6,1,("skip","skip"))) for s,a in zip(ref.SIDES,acts)]


def test_sampling_group_spread_action_coverage_and_path_ties():
    pairs=pairs_fixture();picked=pack.select_clips(pairs)
    assert picked==pack.select_clips(list(reversed(pairs)))
    assert [p["group"] for p in picked]==["g01","g04","g05","g06"]
    assert picked[0]["path"].endswith("g01_c01.avi")
    assert len(pack.select_clips(pairs,2))==2
    assert pack.sample_indices(267)==[0,66,133,199,266]
    assert pack.sample_indices(2)==[0,1]
    assert pack.sample_indices(1)==[0]


@pytest.mark.parametrize("fault",["duplicate_side","missing_side","outside_scope"])
def test_sampling_rejects_bad_pool(fault):
    pairs=pairs_fixture()
    if fault=="duplicate_side":pairs.append(copy.deepcopy(pairs[0]))
    elif fault=="missing_side":pairs.pop()
    else:pairs[0]["path"]="Data/other/v_BodyWeightSquats_g01_c01.avi"
    with pytest.raises(ValueError):pack.select_clips(pairs)


